// Function DECLARATION
function dodaj(a, b) {
  return a + b;
}

// Function EXPRESSION
const odejmij = function (a, b) {
  return a - b;
};

console.log(dodaj(5, 3));    // 8
console.log(odejmij(5, 3));  // 2 - oba dzialaja identycznie PO zdefiniowaniu

// Declaration: hoistowana - mozna wywolac PRZED definicja
console.log(add(2, 3)); // 5 - dziala dzieki hoistingowi
function add(a, b) {
  return a + b;
}

// Expression: NIE jest hoistowana
// console.log(multiply(2, 3)); // TypeError: multiply is not a function
const multiply = function (a, b) {
  return a * b;
};
console.log(multiply(2, 3)); // 6

const operacje = {
  dodawanie: function (a, b) { return a + b; },
  mnozenie: function (a, b) { return a * b; }
};

console.log(operacje.dodawanie(3, 4)); // 7
console.log(operacje.mnozenie(3, 4));  // 12

console.log(policzRabat(100)); // ReferenceError: Cannot access 'policzRabat' before initialization

const policzRabat = function (cena) {
  return cena * 0.9;
};

const policzRabat = function (cena) {
  return cena * 0.9;
};
console.log(policzRabat(100)); // 90 - POPRAWNIE, wywolanie PO deklaracji

// ALBO, jesli potrzebna elastycznosc kolejnosci:
console.log(policzRabatV2(100)); // 90 - dziala nawet PRZED definicja
function policzRabatV2(cena) {
  return cena * 0.9;
}

