console.log(odejmij(10, 4)); // 6

function odejmij(a, b) {
  return a - b;
}

const podziel = function (a, b) {
  return a / b;
};

console.log(podziel(20, 4)); // 5

// gdyby wywolac pomnoz(2, 3) PRZED ponizsza linia, JavaScript zglosilby
// ReferenceError: Cannot access 'pomnoz' before initialization - zmienna
// pomnoz jest zadeklarowana przez const, wiec do momentu wykonania tej
// linii znajduje sie w Temporal Dead Zone (nie jest hoistowana jak
// function declaration)

const pomnoz = function (a, b) {
  return a * b;
};

console.log(pomnoz(2, 3)); // 6

function policzSrednia(a, b, c) {
  return (a + b + c) / 3;
}

console.log(policzSrednia(2, 4, 6));   // 4
console.log(policzSrednia(10, 20, 30)); // 20

const policzPole = function (bok) {
  return bok * bok;
};

console.log(policzPole(5)); // 25

console.log(obliczCene(100, 0.23)); // 123

function obliczCene(cenaBazowa, podatek) {
  return cenaBazowa + cenaBazowa * podatek;
}

const kalkulator = {
  dodaj: function (a, b) { return a + b; },
  odejmij: function (a, b) { return a - b; }
};

console.log(kalkulator.dodaj(10, 5));    // 15
console.log(kalkulator.odejmij(10, 5));  // 5

try {
  console.log(przedstawWynik(42));
} catch (e) {
  console.log(e.name); // "ReferenceError" - const jest w Temporal Dead Zone
}

const przedstawWynik = function (wynik) {
  return `Wynik to: ${wynik}`;
};

console.log(przedstawWynik(42)); // "Wynik to: 42" - POPRAWNIE, po deklaracji

function policzBmi(waga, wzrost) {
  return waga / (wzrost * wzrost);
}

console.log(policzBmi(70, 1.75).toFixed(2)); // "22.86"

const przywitaj = function (imie) {
  return `Czesc, ${imie}!`;
};

console.log(przywitaj("Ala")); // "Czesc, Ala!"

function test() {
  return "pierwsza wersja";
}

function test() {
  return "druga wersja";
}

console.log(test()); // "druga wersja" - druga deklaracja NADPISUJE pierwsza,
// obie maja te sama nazwe w tym samym zasiegu

const policzReszte = function (kwota, zaplacono) {
  return zaplacono - kwota;
};

console.log(policzReszte(45, 50)); // 5
console.log(policzReszte(20, 20)); // 0

const operacje = [
  function (a, b) { return a + b; },
  function (a, b) { return a - b; }
];

console.log(operacje[0](10, 3)); // 13
console.log(operacje[1](10, 3)); // 7

const silnia = function silniaWewn(n) {
  return n <= 1 ? 1 : n * silniaWewn(n - 1);
};

console.log(silnia(5)); // 120

function sprawdzPelnoletnosc(wiek) {
  return wiek >= 18;
}

console.log(sprawdzPelnoletnosc(16)); // false
console.log(sprawdzPelnoletnosc(21)); // true

let operacja;
const tryb = "mnozenie";

if (tryb === "mnozenie") {
  operacja = function (a, b) { return a * b; };
} else {
  operacja = function (a, b) { return a + b; };
}

console.log(operacja(4, 5)); // 20

const zamienNaWielkieLitery = function (tekst) {
  return tekst.toUpperCase();
};

console.log(zamienNaWielkieLitery("javascript")); // "JAVASCRIPT"

function policzPodatek(kwota) {
  return kwota * 0.19;
}

console.log(policzPodatek(1000)); // 190

// gdyby w tym samym pliku (tym samym zasiegu) zdefiniowac DRUGA function
// declaration o nazwie policzPodatek z inna logika, ta DRUGA deklaracja
// calkowicie NADPISALABY pierwsza - wywolanie policzPodatek(...) zawsze
// uzylby ostatniej zdefiniowanej wersji, bez zadnego bledu czy ostrzezenia

const sklep = {
  obliczRabat: function (cena, procent) {
    return cena - cena * (procent / 100);
  }
};

console.log(sklep.obliczRabat(200, 10)); // 180

function wykonajOperacje(a, b, callback) {
  return callback(a, b);
}

function dodaj(a, b) {
  return a + b;
}

console.log(wykonajOperacje(3, 4, dodaj)); // 7

let policz = function (a, b) {
  return a + b;
};

console.log(policz(2, 3)); // 5

policz = function (a, b) {
  return a * b;
};

console.log(policz(2, 3)); // 6

console.log(konwertujCelsjuszNaFahrenheit(100)); // 212 - dziala dzieki hoistingowi

function konwertujCelsjuszNaFahrenheit(c) {
  return c * 9 / 5 + 32;
}

const stworzMnoznik = function (x) {
  return function (y) {
    return x * y;
  };
};

console.log(stworzMnoznik(3)(4)); // 12

function operacjaZewnetrzna() {
  function operacjaWewnetrzna() {
    return "jestem wewnatrz";
  }
  return operacjaWewnetrzna();
}

console.log(operacjaZewnetrzna()); // "jestem wewnatrz"

// operacjaWewnetrzna NIE jest dostepna na zewnatrz - console.log(operacjaWewnetrzna())
// rzucilby ReferenceError: operacjaWewnetrzna is not defined

const pomnozDwa = function (x) {
  return x * 2;
};

console.log(typeof pomnozDwa); // "function"

function policzSume(a, b) {
  return a + b;
}

console.log(policzSume.name); // "policzSume"

const policzRoznice = function (a, b) {
  return a - b;
};

console.log(policzRoznice.name); // "policzRoznice" - JavaScript automatycznie
// nadaje anonimowej function expression nazwe zmiennej, do ktorej zostala
// przypisana (tzw. inferred function name, mechanizm od ES6)

function wypiszPowitanie(imie) {
  console.log(`Witaj, ${imie}!`);
}

const wynik = wypiszPowitanie("Tomek"); // wypisuje "Witaj, Tomek!"
console.log(wynik); // undefined - brak jawnego return zwraca undefined

const polaczTekst = function (a, b) {
  return a + " " + b;
};

console.log(polaczTekst("Dzien", "dobry")); // "Dzien dobry"

function jestParzysta(liczba) {
  return liczba % 2 === 0;
}

console.log(jestParzysta(4)); // true
console.log(jestParzysta(7)); // false

